// UMAMI wrapper for the custom %(kind)s function, generated by bin/init_custom_func.
// It unpacks the batched UMAMI inputs and calls %(function_name)s once per event,
// one GPU thread per event. Write your function in %(body_file)s, there is no need
// to edit this file.

#include "umami.h"

#ifdef __HIPCC__
#include <hip/hip_runtime.h>
typedef hipStream_t gpuStream_t;
#define gpuGetLastError hipGetLastError
#define gpuSuccess hipSuccess
#define UMAMI_GPU_DEVICE UMAMI_DEVICE_HIP
#else
#include <cuda_runtime.h>
typedef cudaStream_t gpuStream_t;
#define gpuGetLastError cudaGetLastError
#define gpuSuccess cudaSuccess
#define UMAMI_GPU_DEVICE UMAMI_DEVICE_CUDA
#endif

#define CUSTOM_IS_PDF %(is_pdf)d
#define CUSTOM_OUTPUT_KEY %(output_key)s

// the function body is compiled into this translation unit
#include "%(body_file)s"

namespace {

constexpr int thread_count = 256;
int dummy_instance;

#if CUSTOM_IS_PDF
constexpr UmamiInputKey input_keys[] = {
    UMAMI_IN_MOMENTUM_FRACTION, UMAMI_IN_SCALE, UMAMI_IN_PDG_ID, UMAMI_IN_BEAM_INDEX
};

__global__ void evaluate(
    std::size_t count,
    const double* x,
    const double* q,
    const int* pdg_id,
    const int* beam_index,
    double* output
) {
    std::size_t i = blockDim.x * blockIdx.x + threadIdx.x;
    if (i < count) {
        output[i] = %(function_name)s(beam_index[i], pdg_id[i], x[i], q[i]);
    }
}
#else
constexpr UmamiInputKey input_keys[] = {
    UMAMI_IN_MOMENTA, UMAMI_IN_PARTICLE_COUNT, UMAMI_IN_PDG_IDS
};
// largest particle count supported by the GPU wrapper
constexpr int max_particle_count = 32;

__global__ void evaluate(
    std::size_t count,
    std::size_t stride,
    const double* momenta,
    const int* particle_count,
    const int* pdg_ids,
    double* output
) {
    std::size_t i = blockDim.x * blockIdx.x + threadIdx.x;
    if (i >= count) {
        return;
    }
    int n = particle_count[i];
    int event_pdg_ids[max_particle_count];
    double event_momenta[max_particle_count][4];
    // column-major layout with the batch dimension contiguous
    for (int j = 0; j < n; ++j) {
        event_pdg_ids[j] = pdg_ids[stride * j + i];
        for (int k = 0; k < 4; ++k) {
            event_momenta[j][k] = momenta[stride * (n * k + j) + i];
        }
    }
    output[i] = %(function_name)s(n, event_pdg_ids, event_momenta);
}
#endif

struct KeyTables {
    bool inputs[UMAMI_INPUT_KEY_COUNT] = {};
    bool outputs[UMAMI_OUTPUT_KEY_COUNT] = {};
    KeyTables() {
        for (auto key : input_keys) {
            inputs[key] = true;
        }
        outputs[CUSTOM_OUTPUT_KEY] = true;
        outputs[UMAMI_OUT_GPU_STREAM] = true;
    }
};
const KeyTables key_tables;

} // namespace

extern "C" {

UmamiStatus umami_get_meta(UmamiMetaKey meta_key, void* result) {
    if (meta_key == UMAMI_META_DEVICE) {
        *static_cast<UmamiDevice*>(result) = UMAMI_GPU_DEVICE;
        return UMAMI_SUCCESS;
    }
    return UMAMI_ERROR_UNSUPPORTED_META;
}

UmamiStatus umami_supported_inputs(bool const** supported, int* count) {
    *supported = key_tables.inputs;
    *count = UMAMI_INPUT_KEY_COUNT;
    return UMAMI_SUCCESS;
}

UmamiStatus umami_required_inputs(bool const** required, int* count) {
    return umami_supported_inputs(required, count);
}

UmamiStatus umami_supported_outputs(bool const** supported, int* count) {
    *supported = key_tables.outputs;
    *count = UMAMI_OUTPUT_KEY_COUNT;
    return UMAMI_SUCCESS;
}

UmamiStatus umami_initialize(UmamiHandle* handle, char const*) {
    *handle = &dummy_instance;
    return UMAMI_SUCCESS;
}

UmamiStatus umami_set_parameter(UmamiHandle, char const*, double, double) {
    return UMAMI_ERROR_NOT_IMPLEMENTED;
}

UmamiStatus umami_get_parameter(UmamiHandle, char const*, double*, double*) {
    return UMAMI_ERROR_NOT_IMPLEMENTED;
}

UmamiStatus umami_matrix_element(
    UmamiHandle,
    std::size_t count,
    std::size_t stride,
    std::size_t offset,
    std::size_t input_count,
    UmamiInputKey const* input_keys_in,
    void const* const* inputs,
    std::size_t output_count,
    UmamiOutputKey const* output_keys,
    void* const* outputs
) {
    double* output = nullptr;
    gpuStream_t stream = nullptr;
    for (std::size_t i = 0; i < output_count; ++i) {
        if (output_keys[i] == CUSTOM_OUTPUT_KEY) {
            output = static_cast<double*>(outputs[i]) + offset;
        } else if (output_keys[i] == UMAMI_OUT_GPU_STREAM) {
            stream = static_cast<gpuStream_t>(outputs[i]);
        } else {
            return UMAMI_ERROR_UNSUPPORTED_OUTPUT;
        }
    }
    if (output == nullptr || count == 0) {
        return UMAMI_SUCCESS;
    }
    unsigned int block_count = (count + thread_count - 1) / thread_count;

#if CUSTOM_IS_PDF
    const double* x = nullptr;
    const double* q = nullptr;
    const int* pdg_id = nullptr;
    const int* beam_index = nullptr;
    for (std::size_t i = 0; i < input_count; ++i) {
        switch (input_keys_in[i]) {
        case UMAMI_IN_MOMENTUM_FRACTION:
            x = static_cast<const double*>(inputs[i]) + offset;
            break;
        case UMAMI_IN_SCALE:
            q = static_cast<const double*>(inputs[i]) + offset;
            break;
        case UMAMI_IN_PDG_ID:
            pdg_id = static_cast<const int*>(inputs[i]) + offset;
            break;
        case UMAMI_IN_BEAM_INDEX:
            beam_index = static_cast<const int*>(inputs[i]) + offset;
            break;
        default:
            return UMAMI_ERROR_UNSUPPORTED_INPUT;
        }
    }
    if (!x || !q || !pdg_id || !beam_index) {
        return UMAMI_ERROR_MISSING_INPUT;
    }
    evaluate<<<block_count, thread_count, 0, stream>>>(
        count, x, q, pdg_id, beam_index, output
    );
#else
    const double* momenta = nullptr;
    const int* particle_count = nullptr;
    const int* pdg_ids = nullptr;
    for (std::size_t i = 0; i < input_count; ++i) {
        switch (input_keys_in[i]) {
        case UMAMI_IN_MOMENTA:
            momenta = static_cast<const double*>(inputs[i]) + offset;
            break;
        case UMAMI_IN_PARTICLE_COUNT:
            particle_count = static_cast<const int*>(inputs[i]) + offset;
            break;
        case UMAMI_IN_PDG_IDS:
            pdg_ids = static_cast<const int*>(inputs[i]) + offset;
            break;
        default:
            return UMAMI_ERROR_UNSUPPORTED_INPUT;
        }
    }
    if (!momenta || !particle_count || !pdg_ids) {
        return UMAMI_ERROR_MISSING_INPUT;
    }
    evaluate<<<block_count, thread_count, 0, stream>>>(
        count, stride, momenta, particle_count, pdg_ids, output
    );
#endif
    return gpuGetLastError() == gpuSuccess ? UMAMI_SUCCESS : UMAMI_ERROR;
}

UmamiStatus umami_free(UmamiHandle) { return UMAMI_SUCCESS; }

} // extern "C"
